SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/jiuwudaishi-115-december-955/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002743；EPUB电子本，纸本及异文待核", "id": "c819fc83-dec5-585e-8874-8eb00977a010"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/jiuwudaishi-115-fengzhou-report/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002742；EPUB电子本，纸本及异文待核", "id": "8431f7df-467d-59b7-a482-aee9208abaea"}, {"title": "旧五代史·卷一百十五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/jiuwudaishi-115-huainan-command/source.txt", "note": "《旧五代史》卷一百十五，段落 jiu-wudaishi-205deb4a7860-p002739；EPUB电子本，纸本及异文待核", "id": "53e4fa1f-1938-54c8-a1e0-d536cf4b80d6"}, {"title": "宋史·巻二百五十一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae49017eccd2548c5c8143213ca3069a4e/content/books/zizhi-tongjian/vol-292/year-0955/part-05/sources/library/songshi-251-hanlingkun-origin/source.txt", "note": "《宋史》巻二百五十一，段落 songshi-9c6e46fee832-p057257；EPUB电子本，纸本及异文待核", "id": "33a3a726-9fb0-52f9-8476-a67d2865e6a0"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7a7159ae