INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "吴廷绍", "aliases": ["吳廷紹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州监军。《通鉴》记其认为边境无事，冬季守淮浪费粮食物资，因此停止把浅防守；刘仁赡上表反对未获采纳。相关确切年份和生卒年未载。", "biography": null, "status": "draft", "id": "b83d337b-6671-506c-a443-85a2ff6efc5a"}, {"name": "刘仁赡", "aliases": ["劉仁贍"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领，刘金之子，字守惠、彭城人。951年以武昌节度使身份率二百艘战舰攻取岳州。《新五代史》还记他早年任左监门卫将军、黄袁二州刺史，后掌亲军。生卒年尚未录入。", "biography": null, "status": "draft", "id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "武行德", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州榆次人。947年受契丹命运送晋朝铠甲兵器，途中与军士夺取兵器、杀契丹监军，继而占据河阳。生卒年尚未录入。", "biography": null, "status": "draft", "id": "e0ed92f8-edb4-574b-83af-85088429a093"}, {"name": "王景（后晋耀州团练使）", "aliases": ["王景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "掖县人，曾任相州刺史。范延光叛乱时，他拒绝服从范延光。938年任耀州团练使。生卒年未载。", "biography": null, "status": "draft", "id": "95c5e667-cc89-51aa-862e-471795aa6956"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "王环（后蜀凤州节度使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "镇州真定人，早年以勇力为孟知祥御者，后掌后蜀宿卫。开运末秦凤等地入蜀后，孟昶任其为凤州节度使。955年十一月凤州陷落时被后周军俘获。与914—929年楚水军将领王环分别保存，无同人证据。生卒年未载。", "biography": null, "status": "draft", "id": "abfc7768-1b27-5f09-bc3e-db6360a31dd2"}, {"name": "赵崇溥", "aliases": ["趙崇溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀凤州都监。955年十一月与威武节度使王环等被后周军俘获，随后因不进食而死，具体死亡时间未载。与后蜀客省使赵崇韬名字不同，未作合并。", "biography": null, "status": "draft", "id": "f9979641-537e-5b1a-be5a-4bae1e47eb64"}, {"name": "刘彦贞", "aliases": ["劉彥貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘信之子，南唐楚州刺史。944年条下追述他改任濠州观察使，迅速前往替代刘崇俊。具体任职年月与生卒年未载。", "biography": null, "status": "draft", "id": "3a86e5c0-cc8e-5120-888d-a75e599e8e30"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：皇甫晖。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "姚凤", "aliases": ["姚鳳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年李璟任他为建州行营都监，与何敬洙、祖全恩率军增援查文徽。生卒年本段未载。", "biography": null, "status": "draft", "id": "74f180a4-a1e3-5952-a5d4-9d936d1a19ac"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "殷崇义", "aliases": ["殷崇義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员。955年后周兵将至，李璟由翰林承旨、户部尚书任其为吏部尚书、知枢密院。生卒年及其他别名待对应史料补核。", "biography": null, "status": "draft", "id": "929f5ee1-ebb3-556e-b4ac-aa35cf7619a6"}, {"name": "白延遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后晋护圣指挥使。946年六月受命与王彦超带所属十营兵赴邢州。生卒年未载；不与皇甫遇等姓名相近将领混同。", "biography": null, "status": "draft", "id": "175ec9b6-d0c6-53ca-985e-f818a4d10d20"}, {"name": "郑仁诲", "aliases": ["鄭仁誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "晋阳人，后周内客省使、恩州团练使。952年三月任枢密副使，新旧五代史同日记载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "f7eb66ac-1c5c-5720-aa2e-9256e75c2b71"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "陈彦禧", "aliases": ["陳彥禧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越元帅府判官。955年受钱弘俶派遣入贡后周；柴荣随后下诏要求吴越出兵攻南唐。生卒年未载，未与其他书中仅有同名的作者强行合并。", "biography": null, "status": "draft", "id": "bde56795-4512-5019-978c-b7c76c743936"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "南唐曾在冬季淮水变浅时派兵守河，称为把浅", "start_year": null, "end_year": null, "time_original": "955年以前或南征前的历年冬季制度回述，起止年未载", "dynasty": "五代十国", "description": "南唐曾在冬季淮水变浅时派兵守河，称为把浅。", "phases": [], "location_name": "淮水", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "50fdc675-96dc-54f9-a7aa-a08be38100d2"}, {"title": "吴廷绍停止冬季把浅防守", "start_year": null, "end_year": null, "time_original": "955年南征以前，具体年份与月日未载", "dynasty": "五代十国", "description": "吴廷绍停止冬季把浅防守。", "phases": [], "location_name": "寿州及淮水防线", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8421b2b3-145d-5836-a487-14d3b3f15463"}, {"title": "刘仁赡上表反对停止把浅，未能阻止", "start_year": null, "end_year": null, "time_original": "吴廷绍停止把浅时，具体年日未载", "dynasty": "五代十国", "description": "刘仁赡上表反对停止把浅，未能阻止。", "phases": [], "location_name": "南唐寿州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "45b09baf-ae62-5d15-a0be-65c1fb87016c"}, {"title": "柴荣任李谷、王彦超统率淮南前军，命韩令坤等十二将随征", "start_year": 955, "end_year": 955, "time_original": "955年十一月乙未朔", "dynasty": "五代十国", "description": "柴荣任李谷、王彦超统率淮南前军，命韩令坤等十二将随征。", "phases": [], "location_name": "后周朝廷至淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ade71749-71b4-5a0c-9700-721850c8700a"}, {"title": "《通鉴》回述汴水唐末溃决，埇桥东南成为积水之地", "start_year": null, "end_year": null, "