INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "person", "field_path": "description", "claim_text": "李璟：是本段南唐君主，史书同时评价其性情与用人。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：唐主性和柔，好文章，而喜人顺己，由是谄谀之臣多进用，政事日乱。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "424f3e92-452e-5acf-85cb-b1cd7d887037", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "evaluation", "claim_text": "《通鉴》认为李璟性情温和、喜爱文章，却喜欢别人顺从自己，以致谄谀者得到任用、政事紊乱。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：唐主性和柔，好文章，而喜人顺己，由是谄谀之臣多进用，政事日乱。；核对说明：这是史家对用人和政治的评价，不当作已量化验证的全部因果。", "status": "draft", "id": "253194b7-f200-554a-8f66-564bcff08203", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "evaluation", "claim_text": "《通鉴》称南唐攻取建州、击败湖南后，李璟更加骄傲，并有扩张天下的志向。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：既克建州，破湖南，益骄，有吞天下之志。；核对说明：所述建州、湖南胜利为既往背景，未重建955年已发生的两场新战役；志向不等于实现。", "status": "draft", "id": "324a755a-bbad-53b0-ac8a-3163e5b693b3", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "biography", "claim_text": "《通鉴》回述李璟曾为李守贞、慕容彦超的叛乱出兵，遥相声援。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：李守贞、慕容彦超之叛，皆为之出师，遥为声援。；核对说明：两次旧事时间不由本955年条强定，保留回述事实；两名叛乱者与南唐君主并非同一人。", "status": "draft", "id": "cfaed31e-0603-5da6-bf4e-ab389a59d055", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "biography", "claim_text": "《通鉴》回述南唐遣使从海路联络契丹和北汉，约定共同图谋中原。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：又遣使自海道通契丹及北汉，约共图中国。值中国多事，未暇与之校。；核对说明：中国在此指中原政权；原段未给各次使行日期，约定不当作同时已经联合出兵。", "status": "draft", "id": "2b76ac0c-484a-5663-92ee-f5b434090e30", "subject_id": "6bf72971-88c3-5187-8f25-98cde2a9554a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "description", "claim_text": "南唐曾在冬季淮水变浅时派兵守河，称为把浅。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：先是，每冬淮水浅涸，唐人常发兵戍守，谓之“把浅”。；核对说明：每冬为长期惯例，不把全部历年戍守写成955年单次命令。", "status": "draft", "id": "6d8cef07-cb30-5ef8-abce-5027052325bb", "subject_id": "50fdc675-96dc-54f9-a7aa-a08be38100d2", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年以前或南征前的历年冬季制度回述，起止年未载", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：先是，每冬淮水浅涸，唐人常发兵戍守，谓之“把浅”。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "b5718661-03ba-5359-b2f6-7708f111d80c", "subject_id": "50fdc675-96dc-54f9-a7aa-a08be38100d2", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "description", "claim_text": "吴廷绍停止冬季把浅防守。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：寿州监军吴廷绍以为疆场无事，坐费资粮，悉罢之。；核对说明：这是寿州监军对费用和边境的判断，不据此认定边境事实上毫无威胁。", "status": "draft", "id": "31ad835a-9777-500f-9b0e-8b70a6085fe1", "subject_id": "8421b2b3-145d-5836-a487-14d3b3f15463", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "955年南征以前，具体年份与月日未载", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：寿州监军吴廷绍以为疆场无事，坐费资粮，悉罢之。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "a98f365c-0895-5995-b596-2eb303865765", "subject_id": "8421b2b3-145d-5836-a487-14d3b3f15463", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "description", "claim_text": "吴廷绍：认为边境无事、守兵耗粮，停止把浅。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：寿州监军吴廷绍以为疆场无事，坐费资粮，悉罢之。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "b608c006-770d-5e2b-9cda-7fa8cc51d295", "subject_id": "b83d337b-6671-506c-a443-85a2ff6efc5a", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "吴廷绍：认为边境无事、守兵耗粮，停止把浅。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：寿州监军吴廷绍以为疆场无事，坐费资粮，悉罢之。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "7358d986-cd87-5373-9e59-7951dc1358ad", "subject_id": "8eeea15a-9d85-56ab-936f-bf48234763b9", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "description", "claim_text": "刘仁赡上表反对停止把浅，未能阻止。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：清淮节度使刘仁赡上表固争，不能得。；核对说明：不能得指反对意见未获采纳，不推定刘仁赡因此免官或被处罚。", "status": "draft", "id": "a4dd21cb-776b-5e60-a350-e5dd6e98b4ab", "subject_id": "45b09baf-ae62-5d15-a0be-65c1fb87016c", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "吴廷绍停止把浅时，具体年日未载", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：清淮节度使刘仁赡上表固争，不能得。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "c9bc9ce7-2f26-5687-9221-209bb45f0dec", "subject_id": "45b09baf-ae62-5d15-a0be-65c1fb87016c", "source_id": "2d7f2f36-61e7-5b33-9ce9-28e1660dcc67"}, {"subject_table": "person", "field_path": "description", "claim_text": "刘仁赡：上表反对撤去冬季防守，未获采纳。", "citation": "卷292·显德二年（955年十一月至十二月及相关追述）·zztj-v292-y0955-p032·原文件第64行", "note": "原文：清淮节度使刘仁赡上表固争，不能得。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "4c64a037-a7cb-5711-a21d-4360c257f7b7", "subject_id": "fbdf8a53-b985-5dda-a5d1-e96cf9d7121c", "source_id": "2d7f2f36-61e7-